import{_ as t,o as i,c as h,a5 as e}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Quản lý toàn diện crawler trên Trend Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-crawler-management/spec.md","filePath":"feature/admin-crawler-management/spec.md"}'),a={name:"feature/admin-crawler-management/spec.md"};function c(r,n,o,d,l,g){return i(),h("div",null,[...n[0]||(n[0]=[e('<h1 id="quan-ly-toan-dien-crawler-tren-trend-pipeline" tabindex="-1">Quản lý toàn diện crawler trên Trend Pipeline <a class="header-anchor" href="#quan-ly-toan-dien-crawler-tren-trend-pipeline" aria-label="Permalink to &quot;Quản lý toàn diện crawler trên Trend Pipeline&quot;">​</a></h1><p>Trạng thái: IMPLEMENTING — BA được người dùng duyệt ngày 2026-11-02; chỉ triển khai dev, chưa deploy production. Ngày: 2026-11-02. Trang: <code>/admin?view=trendPipeline</code>.</p><h2 id="muc-tieu-va-pham-vi" tabindex="-1">Mục tiêu và phạm vi <a class="header-anchor" href="#muc-tieu-va-pham-vi" aria-label="Permalink to &quot;Mục tiêu và phạm vi&quot;">​</a></h2><p>Admin hiện có quản lý cấu hình, session, kết nối, lịch, chạy và theo dõi bộ crawler Facebook/Threads/TikTok trên một trang. Không tạo tài khoản BrandHub, tài khoản mạng xã hội, tài khoản nhà cung cấp hoặc role mới. Dùng lại RBAC Admin và audit hiện tại; không thay đổi hệ thống đăng nhập.</p><p>Mọi thay đổi code/dependency/Dockerfile/hạ tầng được làm trong repo dev, kiểm chứng rồi deploy qua CI/CD. Không sửa code, cài package hoặc tải browser thủ công trên production. Sau khi tính năng được deploy, thao tác cấu hình qua API Admin là luồng vận hành được thiết kế, không phải chỉnh code production.</p><p>Kế thừa admin-trend-pipeline-now, admin-multiplatform-trend-pipeline, admin-trend-source-config và trend-cold-storage. Không thay đổi thuật toán trend, hợp đồng publication, hoặc tự hợp nhất trang legacy crawl/replay/graph.</p><h2 id="hien-trang-đa-xac-minh" tabindex="-1">Hiện trạng đã xác minh <a class="header-anchor" href="#hien-trang-đa-xac-minh" aria-label="Permalink to &quot;Hiện trạng đã xác minh&quot;">​</a></h2><ul><li>Có chạy thủ công, lịch sử, recovery interrupted run, cấu hình lịch/nền tảng và nguồn Facebook.</li><li>Readiness mới có một lý do lỗi; worker consumer, đăng nhập thực tế và proxy chưa được biểu diễn đầy đủ.</li><li>Collector cần dependency/browser/session riêng; API health UP không chứng minh collector hoạt động.</li><li>Config/history/manifest có phần nằm trong filesystem container, cần lưu bền vững.</li><li>Cấu hình session trên production từng thiếu file; cài runtime trực tiếp không tái lập được khi deploy lại.</li></ul><h2 id="danh-sach-ba-va-acceptance-criteria" tabindex="-1">Danh sách BA và acceptance criteria <a class="header-anchor" href="#danh-sach-ba-va-acceptance-criteria" aria-label="Permalink to &quot;Danh sách BA và acceptance criteria&quot;">​</a></h2><p>P0: bắt buộc cho bản vận hành đầu. P1: hoàn thiện quản lý; cần review nhưng có thể triển khai sau.</p><table tabindex="0"><thead><tr><th>ID</th><th>Ưu tiên</th><th>User story / nghiệp vụ</th><th>Acceptance criteria</th></tr></thead><tbody><tr><td>BA-02</td><td>P0</td><td>Admin thấy đầy đủ điều kiện vận hành</td><td>Liệt kê collector, browser, từng session được chọn, proxy, TikTok API, broker, worker, tracking, scheduler, lưu trữ và downstream publication dependencies. Mỗi mục có trạng thái, thời điểm đo, mã lỗi và cách xử lý; timeout là UNKNOWN, không giả định healthy. Lỗi không che các kết quả còn lại.</td></tr><tr><td>BA-03</td><td>P0</td><td>Phân biệt sẵn sàng chạy và đang hoạt động</td><td>Tách manualReady, schedulerHealthy và kết quả run gần nhất. Chỉ điều kiện bắt buộc của nền tảng được chọn chặn start; scheduler dừng không chặn manual. Worker dùng heartbeat/consumer đúng queue; Redis ping không chứng minh pipeline hoàn tất.</td></tr><tr><td>BA-04</td><td>P0</td><td>Admin quản lý nền tảng và nguồn</td><td>Giữ Facebook pages/groups, Threads Trending Now, TikTok hashtag/Creative Center và giới hạn hiện có. Chọn ít nhất một nền tảng; không tự bỏ nền tảng lỗi. Run thủ công có thể chọn tập con rõ ràng mà không âm thầm đổi lịch mặc định. Preview số nguồn, giới hạn và revision trước khi chạy.</td></tr><tr><td>BA-05</td><td>P0</td><td>Admin nạp/thay session Facebook và Threads</td><td>Upload JSON riêng từng nền tảng, giới hạn mặc định đề xuất 1 MiB/file. Validate schema hỗ trợ bởi crawler, cookie domain/name/type, giới hạn số phần tử và loại bỏ trường không cần thiết theo schema. Tên/path do server quyết định. File sai bị từ chối, không thay bản đang dùng. Không có API tải file hoặc đọc cookie.</td></tr><tr><td>BA-06</td><td>P0</td><td>Admin biết session có dùng được hay không</td><td>Phân biệt MISSING, FORMAT_VALID_UNVERIFIED, VERIFIED, EXPIRED_OR_LOGIN_REQUIRED, CHECKPOINT_REQUIRED và CHECK_FAILED. Nút kiểm tra thực hiện probe giới hạn thời gian bằng browser và proxy của nền tảng, không crawl feed hàng loạt. Không kết luận session hết hạn khi lỗi mạng. Timestamp/cookie expiry chỉ tham khảo, không bảo đảm hiệu lực đăng nhập.</td></tr><tr><td>BA-07</td><td>P0</td><td>Thay session không phá run đang chạy</td><td>Lưu version bất biến, cập nhật active pointer nguyên tử; mỗi run chốt version và có bản làm việc riêng để browser cập nhật cookie. Session mới áp dụng run kế tiếp. Admin có thể ngừng dùng session cho run tương lai; UI cảnh báo run đang chạy vẫn dùng bản snapshot. Chỉ giữ bản còn tham chiếu; chính sách hết hạn bản cũ ở phần quyết định.</td></tr><tr><td>BA-08</td><td>P0</td><td>Admin quản lý proxy hiện có</td><td>Xem trạng thái đã cấu hình, kiểm tra kết nối và thay endpoint/credential của provider đang dùng. Trường secret chỉ nhập thay mới, không trả lại giá trị. Hiển thị lỗi auth/quota/timeout khi nhận diện được, không tự suy diễn. Không tự chuyển sang IP trực tiếp khi proxy lỗi. Chặn URL/protocol/đích nội bộ ngoài allowlist server; không biến probe thành proxy truy cập tùy ý.</td></tr><tr><td>BA-09</td><td>P0</td><td>Admin thay cấu hình TikTok API hiện có</td><td>Chỉ hỗ trợ provider hiện tại và endpoint trong allowlist triển khai; secret write-only. Không tạo account/key mới. Hiển thị chưa cấu hình/kết nối được/auth lỗi/không xác minh được. Không tự gọi API tốn phí khi mở trang. Các key LLM/AWS/Neo4j không nằm trong form này.</td></tr><tr><td>BA-10</td><td>P0</td><td>Admin quản lý lịch chạy</td><td>Bật/tắt lịch, chọn giờ theo timezone IANA hiển thị rõ, preview ít nhất 3 lần chạy kế tiếp. Preserve cron tùy chỉnh hiện có. Không tự diễn giải giờ UTC thành giờ Việt Nam. Chỉ một scheduler owner, có heartbeat; lịch bật nhưng scheduler chết phải báo lỗi. Pause lịch không hủy run hiện tại.</td></tr><tr><td>BA-11</td><td>P0</td><td>Admin chạy ngay hoặc chạy kiểm tra nhỏ</td><td>Chạy cùng pipeline thật; chế độ kiểm tra giới hạn nguồn/bài nhưng mặc định không publish vào live, đánh dấu rõ mục đích. Start trả accepted với run ID; chống double click và request trùng. Khóa giữa manual/scheduler/recovery, worker API nhiều process. Snapshot cấu hình/session/proxy version cho run; probe có chi phí cần thao tác rõ ràng.</td></tr><tr><td>BA-12</td><td>P0</td><td>Admin theo dõi từ crawl đến live trend</td><td>Hiển thị tiến độ từng nền tảng/nguồn, bài thu được, dedup/bỏ qua, batch queued/processing/completed/failed, DB saved, Redis published và resolution. Không giả lập phần trăm khi chưa biết tổng. Chỉ COMPLETED khi run đáp ứng publication/resolution contract hiện có; PARTIAL/FAILED/INTERRUPTED phải phản ánh đúng dữ liệu thực.</td></tr><tr><td>BA-13</td><td>P0</td><td>Admin dừng thu thập có kiểm soát</td><td>Nút yêu cầu dừng có xác nhận, STOP_REQUESTED rồi terminal status khi xác nhận dừng. Collector ngừng bắt đầu nguồn mới, flush output và đóng manifest an toàn; các batch đã nhận được tiếp tục xử lý. UI phân biệt collection stopped với downstream still processing. Không xóa queue, kill worker chung hoặc báo đã dừng khi chưa có xác nhận. Timeout dừng báo rõ và giữ recoverability.</td></tr><tr><td>BA-14</td><td>P0</td><td>Admin đọc lỗi và log an toàn</td><td>Log/sự kiện có run/source/stage/time và mã lỗi; phân trang, giới hạn retention. Không trả cookie, auth header, proxy credential, presigned URL hoặc env dump. Có kiểm thử redaction; log nhạy cảm không gửi analytics. HTTP/proxy timeout không bị gộp thành lỗi session.</td></tr><tr><td>BA-15</td><td>P0</td><td>Admin xem lịch sử và phục hồi</td><td>Lọc theo thời gian/nền tảng/trạng thái; xem snapshot metadata và tổng kết. Giữ recovery interrupted run hiện có: dùng dữ liệu đã lưu và ID gốc, không tự crawl lại hay publish trùng. Restart dịch vụ vẫn đọc được lịch sử, manifest, receipt và progress. Hết dữ liệu phục hồi phải giải thích rõ.</td></tr><tr><td>BA-16</td><td>P1</td><td>Admin chạy lại phần thất bại</td><td>Preview nguồn/batch sẽ retry, chi phí và tác động live trước khi xác nhận. Phân biệt retry batch với crawl mới; chống trùng và không retry vô hạn. Không cho push payload tùy ý hoặc bulk requeue DLQ từ trình duyệt.</td></tr><tr><td>BA-18</td><td>P0</td><td>Thao tác quản trị được bảo vệ và truy vết</td><td>Kiểm tra quyền server-side cho tất cả endpoint; CSRF phù hợp cơ chế auth hiện có; audit actor/action/environment/version/result. Không chứa secret. TLS các chặng mang secret, mã hóa secret/session khi lưu, quyền tối thiểu và khóa tách khỏi ciphertext; frontend không lưu secret vào cache/localStorage.</td></tr><tr><td>BA-19</td><td>P0</td><td>Cấu hình không mất hoặc ghi đè nhau</td><td>Config có optimistic revision, atomic update, lịch sử metadata và lỗi stale rõ ràng. Runtime config/session/manifest/control/history dùng persistent storage và đúng UID/GID. Bản chạy giữ snapshot cũ; secret rotation không tự restart service hoặc đổi run đang chạy.</td></tr><tr><td>BA-20</td><td>P1</td><td>Admin thấy bất thường chủ động</td><td>Cảnh báo trong trang khi không có consumer, queue tăng, run lâu không tiến triển, proxy/session lỗi hoặc lâu chưa publish. Có mốc lastChecked; ngưỡng cấu hình qua deployment. Không gửi email/Slack hoặc tạo automation ngoài app ở phạm vi này.</td></tr></tbody></table><h2 id="quy-tac-nghiep-vu-trong-yeu" tabindex="-1">Quy tắc nghiệp vụ trọng yếu <a class="header-anchor" href="#quy-tac-nghiep-vu-trong-yeu" aria-label="Permalink to &quot;Quy tắc nghiệp vụ trọng yếu&quot;">​</a></h2><ul><li>Không tạo account mới ở bất kỳ hệ thống nào; chỉ dùng admin và tài khoản crawler/provider đã có.</li><li>Không yêu cầu nhập mật khẩu/OTP mạng xã hội vào BrandHub. Người vận hành đăng nhập thủ công bằng công cụ local rồi nạp session.</li><li>Kiểm tra tĩnh không gọi provider; health polling không crawl, không rotate proxy và không chạy inference. Probe từ xa có nút riêng, rate limit và thời hạn.</li><li>Readiness có freshness/UNKNOWN. Lỗi nền tảng không chọn không chặn run được chọn. Không dùng <code>ready=true</code> như cam kết nhà cung cấp sẽ không lỗi sau đó.</li><li>Dependency/browser thiếu: hiển thị hướng xử lý qua dev/CI/CD; UI không có nút pip install, shell, sửa env tùy ý hay restart container.</li><li>Queue và DLQ mặc định chỉ đọc; không purge. Retry chỉ theo BA-16 nếu được duyệt.</li><li>Tránh ghi snapshot rỗng lên live khi toàn bộ nguồn thất bại; run thu thập thành công nhưng thực sự không có trend phải được phân biệt. Quy tắc publication này cần review riêng vì là thay đổi so với đường ghi hiện tại.</li><li>Session/proxy là secret; không nhét vào snapshot config hoặc audit. Run snapshot chỉ tham chiếu opaque version ID.</li></ul><h2 id="ui-ux-va-trang-thai" tabindex="-1">UI/UX và trạng thái <a class="header-anchor" href="#ui-ux-va-trang-thai" aria-label="Permalink to &quot;UI/UX và trạng thái&quot;">​</a></h2><p>Trang hiển thị lần kiểm tra; khu tình trạng vận hành và lỗi cần xử lý; run đang hoạt động; các mục Tổng quan, Nguồn &amp; giới hạn, Session &amp; kết nối, Lịch chạy, Lịch sử. Chi tiết run hiển thị ngay trong trang, giữ được back/deep link. Form dài dùng toàn chiều rộng; dialog ngắn cho xác nhận stop/revoke/retry. Giữ màu/theme/component BrandHub. Không hiển thị nhãn môi trường hoặc phiên bản ứng dụng. Kiểm tra danh sách/số lượng trend và dữ liệu đầu ra dùng trang <code>/admin?view=trends</code> hiện có; trang pipeline chỉ giữ trạng thái các bước xử lý của từng run theo BA-12.</p><p>Giữ dữ liệu form chưa lưu khi polling; không overwrite khi người dùng đang nhập. Error gần trường, focus tới lỗi đầu; feedback accessible qua role/status, không chỉ màu. Hỗ trợ bàn phím, mobile/tablet/desktop, light/dark.</p><p>Các nhóm i18n mới song song trong <code>src/i18n/locales/{vi,en}/admin.json</code>: <code>admin.crawler.health.*</code>, <code>sources.*</code>, <code>sessions.*</code>, <code>connections.*</code>, <code>schedule.*</code>, <code>runs.*</code>, <code>logs.*</code>, <code>audit.*</code>, <code>errors.*</code>, <code>confirm.*</code>. Tái sử dụng key hiện có nếu cùng nghĩa; mọi chuỗi/enum hiển thị mới phải có key vi/en.</p><h2 id="api-contract-đe-xuat-chua-chot-implementation" tabindex="-1">API contract đề xuất, chưa chốt implementation <a class="header-anchor" href="#api-contract-đe-xuat-chua-chot-implementation" aria-label="Permalink to &quot;API contract đề xuất, chưa chốt implementation&quot;">​</a></h2><p>Giữ Business <code>/api/v1/admin/ai/trend-pipeline</code> và AI internal prefix hiện có. Mở rộng status thành <code>checks[]</code> (component/platform/status/code/checkedAt/remedy), thêm manual/scheduled readiness và heartbeat age. Giữ tương thích field cũ trong giai đoạn chuyển đổi.</p><p>Các nhóm endpoint thêm: session metadata + upload/revoke/probe; proxy/TikTok masked metadata + replace/probe; run preview/start/stop/events/detail; history pagination. Không thêm endpoint output summary; dùng trang trends hiện có để kiểm tra đầu ra. Tất cả command dùng ID và enum được kiểm tra, không nhận shell/path/CLI tùy ý. Metadata GET không chứa secret; command accepted trả operation ID/status, probe async khi cần. 400 invalid, 401/403 auth, 404 unknown, 409 stale/busy/state conflict, 413 quá dung lượng, 429 rate limit, 503 unavailable; lỗi provider chuẩn hóa và redacted.</p><h2 id="cac-quyet-đinh-can-review" tabindex="-1">Các quyết định cần review <a class="header-anchor" href="#cac-quyet-đinh-can-review" aria-label="Permalink to &quot;Các quyết định cần review&quot;">​</a></h2><ol><li>Duyệt P0 cho bản đầu; BA-16 retry chọn lọc và BA-20 cảnh báo là P1.</li><li>Session/proxy/TikTok secret đều quản trị write-only trong cùng trang; không thêm trang quản lý account hoặc generic env editor.</li><li>Đề xuất giữ tối đa 1 session trước đó trong 24 giờ để khôi phục, chỉ xóa sau khi không còn run tham chiếu; metadata audit giữ theo chính sách hệ thống. Không hứa có thể thu hồi cookie phía Facebook/Threads bằng việc xóa file tại BrandHub.</li><li>Timezone mặc định đề xuất Asia/Ho_Chi_Minh; migration lịch cũ giữ nguyên thời điểm chạy thực tế, chỉ đổi giờ khi admin xác nhận.</li><li>Kiểm tra nhỏ mặc định không publish live. Failed-all-sources không thay thế snapshot tốt đang có; kết quả empty hợp lệ có chính sách riêng.</li><li>Triển khai đầu trên cùng một AI host và scheduler owner hiện có, không thêm nền tảng orchestration hoặc multi-host crawler.</li></ol><h2 id="definition-of-done-va-ngoai-pham-vi" tabindex="-1">Definition of Done và ngoài phạm vi <a class="header-anchor" href="#definition-of-done-va-ngoai-pham-vi" aria-label="Permalink to &quot;Definition of Done và ngoài phạm vi&quot;">​</a></h2><p>BA được duyệt, code/dev checks và security/integration checks đạt; migration persistent state có backup/rollback; build image chứa dependency/browser đúng user; scheduler được quản lý bằng deployment; E2E chứng minh run và publication trung thực. Chưa deploy production khi người dùng chưa duyệt BA/triển khai. Không tạo account, không đổi thuật toán scoring, không sửa trực tiếp production và không mở API hạ tầng tổng quát.</p><h2 id="bo-sung-chan-đoan-local-2026-11-02" tabindex="-1">Bổ sung chẩn đoán local (2026-11-02) <a class="header-anchor" href="#bo-sung-chan-đoan-local-2026-11-02" aria-label="Permalink to &quot;Bổ sung chẩn đoán local (2026-11-02)&quot;">​</a></h2><p>Readiness phải kiểm tra bằng đúng Python của runner, phân biệt BROWSER_DEPENDENCIES_MISSING, BROWSER_MISSING, BROWSER_CHECK_TIMEOUT và BROWSER_CHECK_UNAVAILABLE. Không mặc định mọi runtime là Docker. Trên Windows không phụ thuộc event loop có hỗ trợ asyncio subprocess; polling không cài/download browser.</p><h2 id="sua-loi-proxy-docker-2026-11-02" tabindex="-1">Sửa lỗi proxy Docker (2026-11-02) <a class="header-anchor" href="#sua-loi-proxy-docker-2026-11-02" aria-label="Permalink to &quot;Sửa lỗi proxy Docker (2026-11-02)&quot;">​</a></h2><p>Proxy runtime không phụ thuộc đọc/ghi .env trong container. Proxy từ provider phải được truyền trong bộ nhớ tới browser/tiến trình con ngay lần đầu và khi retry. Khi provider/proxy lỗi, dừng trước khi quét toàn bộ nguồn; log chỉ mã lỗi an toàn. Giữ lựa chọn proxy cố định và kết nối trực tiếp rõ ràng; không đổi session hoặc production khi sửa dev.</p><h2 id="session-ram-theo-yeu-cau-2026-11-02" tabindex="-1">Session RAM theo yêu cầu (2026-11-02) <a class="header-anchor" href="#session-ram-theo-yeu-cau-2026-11-02" aria-label="Permalink to &quot;Session RAM theo yêu cầu (2026-11-02)&quot;">​</a></h2><p>Session Facebook/Threads do admin nạp chỉ giữ trong RAM của một API process; không cần CRAWLER_SECRET_KEY_FILE, không ghi session ra file hoặc Redis. Restart/deploy mất session và UI phải nói rõ yêu cầu nạp lại. Thay/revoke không đổi snapshot của run đang chạy. Proxy/TikTok giữ cơ chế mã hóa hiện có, không mở khóa các trường này khi thiếu key.</p><h2 id="deploy-disk-guard-2026-11-02" tabindex="-1">Deploy disk guard (2026-11-02) <a class="header-anchor" href="#deploy-disk-guard-2026-11-02" aria-label="Permalink to &quot;Deploy disk guard (2026-11-02)&quot;">​</a></h2><p>Deploy phải kiểm tra disk/inode trước pull image; chỉ dọn image AI cũ không được container nào sử dụng, giữ một image dự phòng và target image. Không đụng volume/container/service khác. Thiếu dung lượng sau dọn thì dừng trước khi sửa compose, giữ dịch vụ hiện tại.</p><h2 id="sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" tabindex="-1">Sửa quyền volume và chẩn đoán rollback (2026-11-02) <a class="header-anchor" href="#sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" aria-label="Permalink to &quot;Sửa quyền volume và chẩn đoán rollback (2026-11-02)&quot;">​</a></h2><p>Trước khi recreate AI service, deployment chuẩn bị thư mục volume crawler cho appuser của image mới. Chỉ thay owner/quyền trong /app/data/crawler, không đổi owner toàn /app/data hoặc dữ liệu dịch vụ khác. Lỗi init chặn rollout. Thu metadata health và log startup đã che secret trước rollback.</p><h2 id="retention-khi-rollout-that-bai-2026-11-02" tabindex="-1">Retention khi rollout thất bại (2026-11-02) <a class="header-anchor" href="#retention-khi-rollout-that-bai-2026-11-02" aria-label="Permalink to &quot;Retention khi rollout thất bại (2026-11-02)&quot;">​</a></h2><p>Retention không chọn image unused mới hơn bản đang được container sử dụng làm bản dự phòng; các image như vậy có thể là rollout thất bại/prefetch, chỉ bảo vệ nếu là target hiện tại hoặc được container tham chiếu. Giữ ngưỡng disk 6 GiB, không giảm để bypass.</p><h2 id="tong-quan-chi-hien-thi-lan-chay-gan-nhat-2026-11-02" tabindex="-1">Tổng quan chỉ hiển thị lần chạy gần nhất (2026-11-02) <a class="header-anchor" href="#tong-quan-chi-hien-thi-lan-chay-gan-nhat-2026-11-02" aria-label="Permalink to &quot;Tổng quan chỉ hiển thị lần chạy gần nhất (2026-11-02)&quot;">​</a></h2><p>Tab overview hiển thị tối đa một run: run đang chạy nếu có, nếu không chọn history có startedAt mới nhất, kể cả completed/failed/interrupted. Các run khác xem ở tab lịch sử. Giữ recovery cho run gần nhất bị gián đoạn. Không thêm text/i18n key; giữ theme light/dark và điều hướng bàn phím hiện có.</p><h2 id="thu-muc-worker-co-quyen-ghi-2026-11-03" tabindex="-1">Thư mục worker có quyền ghi (2026-11-03) <a class="header-anchor" href="#thu-muc-worker-co-quyen-ghi-2026-11-03" aria-label="Permalink to &quot;Thư mục worker có quyền ghi (2026-11-03)&quot;">​</a></h2><p>Worker lưu batch/label-check vào /app/data/crawler/trend_runs, trong volume có quyền appuser. Không đổi owner toàn /app/data. Giữ dữ liệu cũ; không tự replay DLQ hoặc dừng run production.</p><h2 id="cai-browser-on-đinh-trong-build-2026-11-03" tabindex="-1">Cài browser ổn định trong build (2026-11-03) <a class="header-anchor" href="#cai-browser-on-đinh-trong-build-2026-11-03" aria-label="Permalink to &quot;Cài browser ổn định trong build (2026-11-03)&quot;">​</a></h2><p>Build cài đúng binary theo phiên bản CloakBrowser đã pin, không chạy auto-update daemon trong installer ngắn hạn. Giữ fail-fast khi download/kiểm tra binary lỗi, không nuốt exit 139.</p><h2 id="gioi-han-ram-ai-4-5-gib-2026-11-03" tabindex="-1">Giới hạn RAM AI 4.5 GiB (2026-11-03) <a class="header-anchor" href="#gioi-han-ram-ai-4-5-gib-2026-11-03" aria-label="Permalink to &quot;Giới hạn RAM AI 4.5 GiB (2026-11-03)&quot;">​</a></h2><p>AI Service có giới hạn 4.5 GiB (4608 MiB), thay 2300 MiB, theo yêu cầu sau OOM run 20261103_012405. Đây là giới hạn container, không phải RAM được giữ riêng. Không sửa trực tiếp production.</p>',44)])])}const p=t(a,[["render",c]]);export{s as __pageData,p as default};
